#include <vector>
#include <cstddef>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    int globalMax = 0;

    #pragma omp parallel for reduction(max:globalMax) schedule(static)
    for (std::size_t i = 0; i < N; ++i) {
        int deg = 0;
        const std::size_t rowBase = i * N;

        for (std::size_t j = 0; j < N; ++j) {
            deg += (A[rowBase + j] != 0) ? 1 : 0;
        }

        if (deg > globalMax) globalMax = deg;
    }

    return globalMax;
}
